// Находим кнопку
const btn = document.querySelector("button");

// Подписываемся на клик
btn.addEventListener("click", function(event) {
  // event — объект с информацией о событии
  console.log("Кнопка нажата!");
  console.log(event.type);     // "click"
  console.log(event.target);   // элемент, на который нажали
});

// event.target — элемент, который вызвал событие

const btn = document.querySelector("button");

// Несколько обработчиков на одно событие
btn.addEventListener("click", () => console.log("Первый"));
btn.addEventListener("click", () => console.log("Второй"));
// При клике: "Первый" → "Второй" — все сработают!

// Разные события
btn.addEventListener("mouseover", () => console.log("Мышь на кнопке"));
btn.addEventListener("mouseout", () => console.log("Мышь ушла"));

document.addEventListener("keydown", (event) => {
  console.log("Клавиша:", event.key);      // какая клавиша
  console.log("Код:", event.code);          // код клавиши
  console.log("Ctrl нажат:", event.ctrlKey); // была ли нажата Ctrl
});

// event.key — символ клавиши ('a', 'Enter', 'Escape')
// event.code — физический код ('KeyA', 'Enter', 'Escape')

